    subsDesc: 'क्रिएटर सीधे अपनी प्रोफ़ाइल से सब्सक्रिप्शन बेचते हैं. प्लान्स की कीमत अमेरिकी डॉलर में होती है और उन्हें DeHub टोकन में लाइव कीमत पर भुगतान किया जाता है, और क्रिएटर का शेयर सीधे उनके वॉलेट में आता है, जो DeHub के बैज - स्तरीय शुल्क से कम है। सब्सक्राइबर - ओनली पोस्ट एक असली गेट हैं: जिन लोगों ने सब्सक्राइब नहीं किया है, वे पोस्ट नहीं, बल्कि वन - लाइन टीज़र देखते हैं।',
