    spDescTeamUp: 'अधिकतम सात अन्य खातों के साथ वॉलेट पावर को मिलाएं। टीम में हर कोई बैज पहनता है पूल बैलेंस अनलॉक करता है, और इसकी कोई कीमत नहीं है। एक टीम निजी हो सकती है, इसलिए लोग इसमें शामिल होने के लिए कहते हैं और मालिक उन्हें मंज़ूरी देता है।',
    feedsHomeDesc: 'टेक्स्ट, इमेज, लेख, वीडियो, ऑडियो और लाइव पोस्ट की एक मिश्रित फ़ीड। लाइक, कमेंट, रीपोस्ट, कोटेशन, बुकमार्क और टोकन टिपिंग को हर कार्ड में बनाया जाता है, और पोस्ट को गेट किया जा सकता है, पे - पर - व्यू किया जा सकता है या watch2earn पर सेट किया जा सकता है। ताकि कोई भी इसे भर न सके, होम फीड में प्रति दिन प्रत्येक लेखक की पोस्ट की सीमित संख्या होती है: एक बैज के बिना और प्रत्येक बैज स्तर के लिए एक और, मेगालोडन में चौदह तक। सब कुछ अभी भी लेखक की प्रोफ़ाइल पर और निम्नलिखित क्रम में दिखाई देता है।',
    feedsSort: 'छँटाई और फ़िल्टरिंग:',
    feedsSortDesc: 'नवीनतम सॉर्ट टैब में पहले आता है, उसके बाद सगाई के प्रकार, जिसमें अधिकांश सुझाव शामिल हैं। हैशटैग पर टैप करने से फ़ीड फ़िल्टर हो जाती है, आपके द्वारा पहले से देखे गए वीडियो को चिह्नित और छिपाया जा सकता है, और कोई भी लाइव चरण होम के शीर्ष पर बैठता है।',
    feedsReactionsDesc: 'दस प्रतिक्रियाएं लाइक बटन के पीछे बैठती हैं: जैसे, प्यार, सम्मान, गर्म, 100, हंसी, उदास, रोना, पू और नापसंद। नापसंद को छोड़कर हर कोई पोस्ट के कुल योग की ओर मायने रखता है। इसे पसंद करने के लिए किसी पोस्ट पर डबल - टैप करें, इसे पसंद करने के लिए ट्रिपल - टैप करें, और ट्रे खोलने के लिए बटन दबाएँ, जो दिखाता है कि किसने प्रतिक्रिया दी और किसके साथ। कार्ड पर प्रमुख आइकन वह होता है, जिसमें पोस्ट पर जो भी प्रतिक्रिया होती है, वह सबसे ज़्यादा आकर्षित होती है। एक प्रतिक्रिया को रिएक्टर के बैज द्वारा भारित किया जाता है, इसलिए किसने प्रतिक्रिया दी और साथ ही कितने ने किया। सेटिंग में बाएं हाथ का मोड बार के बाईं ओर लाइक बटन को ले जाता है।',
    feedsCommentsDesc: 'प्रत्येक पोस्ट में अपनी पसंद, नापसंद और देखने की संख्या के साथ टिप्पणियां होती हैं। जवाब देने के लिए किसी कमेंट पर टैप करें। जब कोई लेखक खुद को जवाब देता है तो रन एक क्रमांकित धागा बन जाता है। एक क्रिएटर अपनी पोस्ट पर एक कमेंट को पिन कर सकता है; थ्रेड फिर उस पिन के साथ लीड करता है, फिर एक पेड कमेंट एंकर, फिर पांच सबसे ज़्यादा टिप वाली कमेंट्स। क्रिएटर किसी पोस्ट के लिए कॉमन ग्राउंड मोड चालू कर सकते हैं, जो पाठकों से उनके पहले उत्तर से पहले दूसरी तरफ के सबसे मजबूत बिंदु के लिए पूछता है, और टिप्पणी बॉक्स में एआई बटन आपकी टोन की जांच करता है, इसकी शैली बदलता है या वर्तनी और व्याकरण को ठीक करता है। किसी भी टिप्पणी की रिपोर्ट उसके शेयर मेनू से की जा सकती है।',
    feedsMuteDesc: 'किसी भी पोस्ट पर \'मेनू\' से किसी लेखक को म्यूट या ब्लॉक करें। म्यूटिंग उन्हें चुपचाप आपकी फ़ीड से बाहर निकाल देता है और इसे पूर्ववत किया जा सकता है; ब्लॉक करना आगे बढ़ता है, दोनों तरीकों से काम करता है और मैसेजिंग को भी काटता है।',
    feedsDub: 'वीडियो डबिंग:',
