    articlesDesc: 'लॉन्ग - फॉर्म राइटिंग का अपना एक तरीका होता है। संगीतकार को पोस्ट से आर्टिकल पर स्विच करें और आपको एक शीर्षक, 20,000 कैरेक्टर तक का बॉडी, एक फ़ॉर्मेटिंग टूलबार, एक कवर इमेज और यह कैसे पढ़ा जाएगा इसका पूर्वावलोकन मिलेगा। एक लेख किसी भी अन्य पोस्ट की तरह प्रकाशित होता है, इसलिए इसे बख्शीश दी जा सकती है, उद्धृत किया जा सकता है, गेट किया जा सकता है और साझा किया जा सकता है, और लिंक कहीं और पोस्ट किए जाने पर इसे अपना खुद का शेयर कार्ड मिलता है।',
