    step1Title: 'अपना अकाउंट बनाएँ',
    step1Desc: 'Dehub.io खोलें और साइन इन करें पर टैप करें। Google, Apple, Telegram, ईमेल, SMS, पासकी या वॉलेट चुनें। बैकग्राउंड में आपके लिए एक नॉन - कस्टोडियल वॉलेट बनाया गया है — आपके पास चाबियाँ हैं — और गैस प्रायोजित है, इसलिए शुरू करने से पहले फंड करने के लिए कुछ भी नहीं है।',
    step2Title: 'अपनी प्रोफ़ाइल सेट अप करें',
    step2Desc: 'सेटिंग → प्रोफ़ाइल में एक डिस्प्ले नाम, यूज़रनेम, अवतार, कवर फ़ोटो और बायो जोड़ें और अपने दूसरे सोशल अकाउंट को लिंक करें, ताकि आपकी प्रोफ़ाइल आपकी कुल पहुँच दिखा सके। जब आप वहाँ हों, तो सेटिंग → उपस्थिति में एक थीम चुनें, और यदि आप चारों ओर दिखाना चाहते हैं, तो वैकल्पिक निर्देशित वॉकथ्रू लें।',
    step3Title: 'अपनी पहली पोस्ट बनाएँ',
    step3Desc: 'क्रिएट करें पर टैप करें। एक पोस्ट लिखें, इमेज, वीडियो या ऑडियो जोड़ें, लंबे समय तक लिखने के लिए आर्टिकल पर स्विच करें या लाइव हो जाएँ। पोस्टिंग एक दैनिक भत्ता तक मुफ़्त है — बिना बैज के एक दिन में दस टेक्स्ट पोस्ट और एक गीगाबाइट मीडिया। ऑन - चेन पोस्ट को मिंट करना वैकल्पिक है और बाद में किया जा सकता है।',
    step4Title: 'अपने दर्शकों से कमाएँ',
    step4Desc: 'हर पोस्ट को DeHub टोकन में बख्शीश दी जा सकती है। वहाँ से आप सब्सक्रिप्शन बेच सकते हैं, पे - पर - व्यू पोस्ट प्रकाशित कर सकते हैं, डायरेक्ट मैसेज के लिए न्यूनतम टिप सेट कर सकते हैं, स्टोर खोल सकते हैं, इनाम पोस्ट कर सकते हैं और उन लोगों से कमाई करने के लिए अपना संबद्ध लिंक साझा कर सकते हैं जिन्हें आप लाते हैं।',
    step5Title: 'बैज के लिए टोकन होल्ड करें',
    step5Desc: 'DeHub टोकन को होल्ड या स्टेक करने से केकड़ा से मेगालोडन तक एक बैज कमाया जा सकता है। एक बैज आपकी फीस कम करता है, आपके पोस्टिंग भत्ते को बढ़ाता है, सुपरपावर को अनलॉक करता है और आपके विचारों, प्रतिक्रियाओं और वोटों में वजन बढ़ाता है।',
